def compute_order_amount(history_demand, history_inventory, history_lost, holding_cost, lost_sales_cost):
    if len(history_demand) < 1:
        return max(0, 50 - history_inventory[-1] if len(history_inventory) > 0 else 50)

    avg_demand = sum(history_demand[-3:]) / 3 if len(history_demand) >= 3 else sum(history_demand) / len(history_demand)
    recent_volatility = max(history_demand[-3:]) - min(history_demand[-3:]) if len(history_demand) >= 3 else 0
    cost_ratio = lost_sales_cost / (holding_cost + lost_sales_cost)
    safety_stock = avg_demand * cost_ratio * (1 + recent_volatility / avg_demand if avg_demand > 0 else 1)
    target_inventory = avg_demand + safety_stock
    order_amount = max(0, target_inventory - history_inventory[-1])
    return order_amount
